skin:
#s89 .stage{background:linear-gradient(180deg,#f4f8ff,#fff);color:#14263e}
#s89 .d-nav{background:#ffffffcc;border:1px solid #e3ecff;border-radius:14px}
#s89 .d-logo{font-weight:700;color:#1677ff}
#s89 .d-links span{opacity:.62}#s89 .d-links span:hover{opacity:1;color:#1677ff}
#s89 .d-h{font-family:var(--mono);letter-spacing:-.01em;color:#14263e}
#s89 .d-p{color:#5d7290}
#s89 .d-btn{background:#1677ff;color:#fff;border-radius:12px;font-weight:600}
#s89 .d-btn:hover{background:#0e5fd8;box-shadow:0 6px 16px #1677ff3d}
#s89 .d-btn.ghost{background:#eef4ff;color:#1677ff;border:1px solid #cfe0ff}
#s89 .d-input{background:#fff;border:1px solid #d7e5ff;border-radius:999px}
#s89 .d-badge{background:#fff;color:#1677ff;border:1px solid #d7e5ff;border-radius:8px}
#s89 .d-prog{background:#e6efff}#s89 .d-prog i{background:linear-gradient(90deg,#1677ff,#7a5cff)}
#s89 .d-card{background:linear-gradient(135deg,#1b7bff,#7a5cff);border:0;border-radius:18px;color:#fff;box-shadow:0 12px 30px #4a6cff3d}
#s89 .d-card .d-h{color:#fff}#s89 .d-card .d-p{color:#e6ecff}
